entries[104224] = { ["name"] = "Technique: Glyph of Evaporation", ["text"] = "Use: Teaches you how to inscribe a Glyph of Evaporation.\nRequires Pandaria Inscription (1)\nGlyph of Evaporation\nClasses: Mage\nUse: Permanently teaches you this glyph.\n\nReduces the size of your Water Elemental by 15%. Exclusive with: Glyph of the Unbound Elemental Glyph of the Tides Glyph of Storm's Wake Glyph of the Dark Depths Glyph of Steaming Fury Glyph of the Cold Waves\nSell Price:\nRequires Light Parchment , Lion's Ink (3)" }
