entries[104288] = { ["name"] = "Condensed Jademist", ["text"] = "Binds when picked up\nUnique (5)\nUse: Surround yourself with a heavy mist, allowing you to blend into the shadows for 10 sec. Only usable in Pandaria. (5 Min Cooldown)\n\"The Jademist Dancers are known to blend seamlessly into the fog surrounding the island.\"" }
entries[104289] = { ["name"] = "Faintly-Glowing Herb", ["text"] = "Binds when picked up\nUnique (10)\nDuration: 1 day (real time)\nUse: Eat the herb, restoring 206 health every 1 sec. for 10 sec.\n\"This herb appears to be infused with a natural enchantment.\"" }
entries[104290] = { ["name"] = "Sticky Silkworm Goo", ["text"] = "Binds when picked up\nUnique (10)\nUse: Coat an enemy in sticky silk, immobilizing even the strongest creatures for 20 sec. Only usable on the Timeless Isle. (5 Min Cooldown)\n\"The silkworms of the Timeless Isle have adapted a strange and very powerful silk used to catch prey.\"" }
