entries[104303] = { ["name"] = "Rain Stone", ["text"] = "Binds when picked up\nUnique\nUse: Place a Rain Stone that will summon an unnatural rain storm in the surrounding area for 10 min. (1 Hour Cooldown)\n50 Charges\n\"The playful water spirits of Pandaria have a curious connection to the weather.\"\nSell Price:" }
entries[104304] = { ["name"] = "Blizzard Stone", ["text"] = "Binds when picked up\nUnique\nUse: Place a Blizzard Stone that will summon an unnatural snow storm in the surrounding area for 10 min. (1 Hour Cooldown)\n50 Charges\n\"High-ranking Ordon chanters can control the weather, ensuring that snow and rain never fall on the eternal fires of the Ordon Sanctuary.\"\nSell Price:" }
entries[104305] = { ["name"] = "Ashen Stone", ["text"] = "Binds when picked up\nUnique\nUse: Place an Ashen Stone that will summon an ash storm in the surrounding area for 10 min. (1 Hour Cooldown)\n50 Charges\n\"Before attacking, the Ordon yaungol will often summon a storm of ash to blind their foes.\"\nSell Price:" }
entries[104306] = { ["name"] = "Sunset Stone", ["text"] = "Binds when picked up\nUnique\nUse: Place a Sunset Stone that will change the time of day to sunset in the surrounding area for 10 min. (1 Hour Cooldown)\n50 Charges\n\"An odd, and potentially quite dangerous, curio capable of stopping the flow of time in a small area.\"\nSell Price:" }
entries[104307] = { ["name"] = "Jadefire Spirit", ["text"] = "Binds when picked up\nUse: Teaches you how to summon and dismiss this companion.\nRight Click to summon and dismiss your Jadefire Spirit.\nRequires level 1 to 80 ( 80)" }
entries[104308] = { ["name"] = "Akolik's Acid-Soaked Robes", ["text"] = "Heroic\nBinds when picked up\nChest Cloth\n4 Armor\n+1 Intellect\n+7 Stamina\n+ 1 Critical Strike\n+ 1 Mastery\n\nPrismatic Socket\nPrismatic Socket\nPrismatic Socket\nSocket Bonus: + 7 Intellect\n\nDurability 165 / 165\nSell Price:" }
entries[104309] = { ["name"] = "Eternal Kiln", ["text"] = "Binds when picked up\nToy\nUse: Places an Eternal Kiln that increases the spirits of those nearby by 4 and allows cooking. (30 Min Cooldown)\n\"Followers of Ordos carry small cauldrons of fire with them for long journeys into the wilderness.\"" }
entries[104311] = { ["name"] = "Legplates of Unthinking Strife", ["text"] = "Heroic\nBinds when picked up\nLegs Plate\n15 Armor\n+1 [Strength or Intellect]\n+7 Stamina\n+ 2 Haste\n+ 1 Mastery\n\nPrismatic Socket\nPrismatic Socket\nPrismatic Socket\nSocket Bonus: + 7 Strength\n\nDurability 120 / 120\nSell Price:" }
entries[104312] = { ["name"] = "Strange Glowing Mushroom", ["text"] = "Binds when picked up\nUnique (20)\nUse: Heals the user for 5% of maximum health and restores 5% of a class-specific power type every 2 sec for 10 sec.\n\"An odd mushroom found deep within the Cavern of Lost Spirits.\"" }
entries[104313] = { ["name"] = "Golden Moss", ["text"] = "Binds when picked up\nUnique\nTrinket\nEquip: May cause extra gold to drop whenever you kill a target that yields experience or honor. (Proc chance: 10%, 10m cooldown)\n\"The moss is flecked with gold and other precious minerals that have slowly built up over thousands of years in the damp caverns.\"\nSell Price:" }
entries[104314] = { ["name"] = "Dragon P.I.E.", ["text"] = "Use: A surprisingly potent alcoholic beverage.\n\"Handcrafted by Grimthorn Redbeard.\"\nSell Price:" }
entries[104316] = { ["name"] = "Spectral Grog", ["text"] = "Use: Transform into a spectral pirate and gets you drunk to boot. (3 Sec Cooldown)\n\"Gives off an otherworldly aroma.\"\nSell Price:" }
entries[104317] = { ["name"] = "Rotten Helper Box", ["text"] = "Use: Teaches you how to summon this companion.\nRight Click to summon and dismiss your Rotten Little Helper.\n\nEven rotten helpers are very busy year-round, and only have leisure time during the Feast of Winter Veil.\nRequires level 1 to 80 ( 80)" }
entries[104318] = { ["name"] = "Crashin' Thrashin' Flyer Controller", ["text"] = "Binds when picked up\nToy\nUse: Summon and control your Flyer! (30 Sec Cooldown)\nSell Price:" }
entries[104319] = { ["name"] = "Winter Veil Gift", ["text"] = "Binds when picked up\n<Right Click to Open>" }
entries[104320] = { ["name"] = "Cursed Talisman", ["text"] = "Binds when picked up\nUnique\nUse: Banishes the user for 20 sec. (5 Min Cooldown)\n50 Charges\n\"The carvings on the face of the talisman depict a grotto filled with moss. If you squint, you can almost make out a face in the moss bed.\"" }
entries[104321] = { ["name"] = "Captain Zvezdan's Lost Leg", ["text"] = "Binds when picked up\nUnique\nTrinket\nUse: Rap the leg on the ground, summoning the crew of the Barnacle to aid you in combat for 10 min. (1 Hour Cooldown)\nSell Price:" }
entries[104323] = { ["name"] = "The Swineskin", ["text"] = "Binds when picked up\nToy\nUse: Throw the ball to a friendly player. If possible, they will automatically return it.\n\"An inflated pig's bladder wrapped in tough cow leather.\"\nSell Price:" }
entries[104324] = { ["name"] = "Foot Ball", ["text"] = "Binds when picked up\nToy\nUse: Kick the ball to a friendly player. If possible, they will automatically return it.\n\"An inflated kodo bladder wrapped in tough, striped zhevra hide.\"\nSell Price:" }
entries[104325] = { ["name"] = "Tyrannical Gladiator's Cloud Serpent", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This is a flying mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"These cloud serpents always look elegant and slim in classic black.\"\nLegacy" }
entries[104326] = { ["name"] = "Grievous Gladiator's Cloud Serpent", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This is a flying mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"These brilliantly colored cloud serpents have scales that are a mixture of ruby, gold, and nearly violet.\"\nLegacy" }
entries[104327] = { ["name"] = "Prideful Gladiator's Cloud Serpent", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This is a flying mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"These brilliantly colored cloud serpents have scales that range from gold to pink. Or we could call it coral.\"\nLegacy" }
entries[104328] = { ["name"] = "Cauterizing Core", ["text"] = "Binds when picked up\nUnique\nUse: Activate the core, allowing the user to resurrect on death with 20% of health and mana. Only usable in Pandaria. (1 Hour Cooldown)\n20 Charges\n\"A fiery core that holds the living essence imbued into the Molten Guardian.\"" }
entries[104329] = { ["name"] = "Ash-Covered Horn", ["text"] = "Binds when picked up\nUnique\nToy\nMount\n(Account-wide)\nUse: Summons a ridable but uncontrollable Furious Ashhide Mushan. This is a very, VERY fast mount. Can only be used on the Timeless Isle. (1 Min Cooldown)\n\"Perpetually warm to the touch.\"" }
entries[104330] = { ["name"] = "Warped Warning Sign", ["text"] = "Binds when picked up\nUnique\nUse: Place a Warning Sign that lasts for 1 min. A message can be carved into the sign, causing it to last for 1 hour and making it visible to other players. (3 Sec Cooldown)\n5 Charges\n\"The wood of this sign will not last for long.\"" }
